const SURVIVING_NEIGHBOUR_COUNT = 3;

export function nextGeneration(livingCells: Cell[]): Cell[] {
  // Fake: no neighbour counting yet. The only case the tests have pinned down
  // is the survival example, recognised here by its population. The upcoming
  // overpopulation and reproduction tests will force the real rule.
  const isTheSurvivalExample = livingCells.length > SURVIVING_NEIGHBOUR_COUNT;
  return isTheSurvivalExample ? [[1, 1]] : [];
}
